def solve(g):
    for r in range(4):
        for c in range(4):
            if g[r][c] == 0:
                for v in (1, 2, 3, 4):
                    if all(g[r][k] != v for k in range(4)) and all(g[k][c] != v for k in range(4)) and all(g[2*(r//2)+i][2*(c//2)+j] != v for i in range(2) for j in range(2)):
                        g[r][c] = v
                        if solve(g): return True
                        g[r][c] = 0
                return False
    return True
