import heapq
W, H = 5, 5
walls = {(2, 0), (2, 1), (2, 3), (2, 4)}
start, goal = (0, 0), (4, 4)
def h(p):
    return abs(p[0] - goal[0]) + abs(p[1] - goal[1])
open_set = [(h(start), 0, start)]
came, cost = {}, {start: 0}
while open_set:
    _, c, cur = heapq.heappop(open_set)
    if cur == goal:
        break
    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        nb = (cur[0] + dx, cur[1] + dy)
        if not (0 <= nb[0] < W and 0 <= nb[1] < H) or nb in walls:
            continue
        nc = c + 1
        if nb not in cost or nc < cost[nb]:
            cost[nb] = nc
            came[nb] = cur
            heapq.heappush(open_set, (nc + h(nb), nc, nb))
path, node = [], goal
while node != start:
    path.append(node)
    node = came[node]
path.append(start)
path.reverse()
print('path:', ' -> '.join(str(p) for p in path))
print('cost:', cost[goal])

