def solve(n):
    cols, d1, d2, queens = set(), set(), set(), []
    def place(r):
        if r == n:
            return True
        for c in range(n):
            if c not in cols and (r - c) not in d1 and (r + c) not in d2:
                cols.add(c); d1.add(r - c); d2.add(r + c); queens.append(c)
                if place(r + 1):
                    return True
                queens.pop(); cols.discard(c); d1.discard(r - c); d2.discard(r + c)
        return False
    place(0)
    return queens
sol = solve(5)
print('queen columns per row:', sol)
for r, c in enumerate(sol):
    print(''.join('Q' if k == c else '.' for k in range(5)))

